import React from 'react';
import {Composition} from 'remotion';
import {PROJECTS} from './projects';
import {Remake} from './kit/Remake';

// One composition per project. projects.ts is regenerated by new_project.py.
// The scene components travel in a closure, NOT in defaultProps: Remotion serialises defaultProps to
// JSON, which silently drops functions (every scene would render as "missing scene component").
const makeComponent = (entry: (typeof PROJECTS)[number]): React.FC => {
  const C: React.FC = () => <Remake project={entry.project} scenes={entry.scenes} />;
  C.displayName = `Remake_${entry.id}`;
  return C;
};

const COMPONENTS = PROJECTS.map((p) => ({...p, Component: makeComponent(p)}));

export const RemotionRoot: React.FC = () => (
  <>
    {COMPONENTS.map(({id, project, Component}) => (
      <Composition
        key={id}
        id={id}
        component={Component}
        width={project.canvas.width}
        height={project.canvas.height}
        fps={project.canvas.fps}
        durationInFrames={project.durationInFrames}
      />
    ))}
  </>
);
